20	\begin{table}[t]
21	\centering
22	\small
23	\begin{tabular}{lcc}
24	\toprule
25	\textbf{Method} & $\boldsymbol{\eta_{\max}}$ \textbf{sig} & $\boldsymbol{K_{\mathrm{eff}}}$ \textbf{sig} \\
